long minCost(int[] ropes) {
    List<Long> r = new ArrayList<>();
    for (int x : ropes) r.add((long) x);
    long cost = 0;
    while (r.size() > 1) {
        r.sort(Collections.reverseOrder());          // re-sort every round, longest first
        long a = r.remove(r.size() - 1);             // the two shortest are at the end
        long b = r.remove(r.size() - 1);
        cost += a + b;
        r.add(a + b);                                // the joined rope goes back in
    }
    return cost;
}

long long minCost(vector<int>& ropes) {
    vector<long long> r(ropes.begin(), ropes.end());
    long long cost = 0;
    while (r.size() > 1) {
        sort(r.rbegin(), r.rend());                  // re-sort every round, longest first
        long long a = r.back(); r.pop_back();        // the two shortest are at the end
        long long b = r.back(); r.pop_back();
        cost += a + b;
        r.push_back(a + b);                          // the joined rope goes back in
    }
    return cost;
}

function minCost(ropes) {
  const r = [...ropes].sort((a, b) => a - b);   // sort once, shortest first
  let cost = 0;
  while (r.length > 1) {
    const a = r.shift(), b = r.shift();         // the two shortest are at the front
    const joined = a + b;
    cost += joined;
    let lo = 0, hi = r.length;                  // binary search for where the new rope belongs
    while (lo < hi) {
      const mid = (lo + hi) >> 1;
      if (r[mid] < joined) lo = mid + 1; else hi = mid;
    }
    r.splice(lo, 0, joined);                    // insert: shifts up to n ropes
  }
  return cost;
}

long minCost(int[] ropes) {
    List<Long> r = new ArrayList<>();
    for (int x : ropes) r.add((long) x);
    Collections.sort(r);                               // sort once, shortest first
    long cost = 0;
    while (r.size() > 1) {
        long joined = r.remove(0) + r.remove(0);       // the two shortest are at the front
        cost += joined;
        int lo = 0, hi = r.size();                     // binary search for where the new rope belongs
        while (lo < hi) {
            int mid = (lo + hi) >>> 1;
            if (r.get(mid) < joined) lo = mid + 1; else hi = mid;
        }
        r.add(lo, joined);                             // insert: shifts up to n ropes
    }
    return cost;
}

long long minCost(vector<int>& ropes) {
    vector<long long> r(ropes.begin(), ropes.end());
    sort(r.begin(), r.end());                          // sort once, shortest first
    long long cost = 0;
    while (r.size() > 1) {
        long long joined = r[0] + r[1];                // the two shortest are at the front
        r.erase(r.begin(), r.begin() + 2);
        cost += joined;
        r.insert(lower_bound(r.begin(), r.end(), joined), joined);   // shifts up to n ropes
    }
    return cost;
}

function minCost(ropes) {
  const heap = Heap.from(ropes);             // a min-heap of rope lengths, built in O(n)
  let cost = 0;
  while (heap.size() > 1) {
    const a = heap.pop(), b = heap.pop();    // the two shortest ropes
    cost += a + b;                           // joining them costs their total length
    heap.push(a + b);                        // the joined rope goes back in
  }
  return cost;
}

long minCost(int[] ropes) {
    PriorityQueue<Long> heap = new PriorityQueue<>();   // a min-heap of rope lengths
    for (int x : ropes) heap.offer((long) x);
    long cost = 0;
    while (heap.size() > 1) {
        long a = heap.poll(), b = heap.poll();          // the two shortest ropes
        cost += a + b;                                  // joining them costs their total length
        heap.offer(a + b);                              // the joined rope goes back in
    }
    return cost;
}

