    priority_queue<long long, vector<long long>, greater<long long>> heap(ropes.begin(), ropes.end());
    long long cost = 0;
    while (heap.size() > 1) {
        long long a = heap.top(); heap.pop();           // the two shortest ropes
        long long b = heap.top(); heap.pop();
        cost += a + b;                                  // joining them costs their total length
        heap.push(a + b);                               // the joined rope goes back in
    }
